SELECT ?schoolName ?doctype WHERE {
  ?f a <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm> ;
     <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/charterFundingType> "Locally funded" ;
     <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/enrollmentK12> ?k12 ;
     <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/enrollmentAges5To17> ?age517 ;
     <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/schoolName> ?schoolName ;
     <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/hasSchools> ?s .
  ?s a <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/School> ;
     <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/School/doctype> ?doctype .
  BIND((xsd:decimal(?k12) - xsd:decimal(?age517)) AS ?diff)
  {
    SELECT (AVG(xsd:decimal(?k12b) - xsd:decimal(?age517b)) AS ?avgDiff) WHERE {
      ?fb a <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm> ;
          <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/charterFundingType> "Locally funded" ;
          <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/enrollmentK12> ?k12b ;
          <http://bird-bird_california_schools-ontology-20261002-161105/ontology/vkg-bird_california_schools/Frpm/enrollmentAges5To17> ?age517b .
    }
  }
  FILTER(?diff > ?avgDiff)
}

